const isEnabled = !!document.getElementById('ai4a11y-keyboard-nav-styles');
if (!isEnabled) return true;
const links = Array.from(document.querySelectorAll('.ai4a11y-skip-link'));
if (links.length < 2) return false;
for (const link of links) {
  link.focus();
  await new Promise(r => setTimeout(r, 250));
  const r = link.getBoundingClientRect();
  if (r.left < 0 || r.right > 320 || r.top < 0) return false;
  link.blur();
}
return true;

const isEnabled = !!document.getElementById('ai4a11y-keyboard-nav-styles');
if (!isEnabled) return true;

document.dispatchEvent(new KeyboardEvent('keydown', { key: 'o', code: 'KeyO', altKey: true, bubbles: true }));
await new Promise(r => setTimeout(r, 60));

const badges = Array.from(document.querySelectorAll('.ai4a11y-tab-badge'));
if (badges.length === 0) return false;
for (const b of badges) {
  if (b.style.display !== 'none') {
    const r = b.getBoundingClientRect();
    if (r.left < 0 || r.right > 320) return false;
  }
}

document.dispatchEvent(new KeyboardEvent('keydown', { key: 'o', code: 'KeyO', altKey: true, bubbles: true }));
await new Promise(r => setTimeout(r, 60));
return true;

const isEnabled = !!document.getElementById('ai4a11y-keyboard-nav-styles');
const btn = document.getElementById('btn-normal');
if (!btn) return false;
if (!isEnabled) return true;

btn.focus();
const s = window.getComputedStyle(btn);
const w = parseFloat(s.outlineWidth) || 0;
const res = w >= 3 && s.outlineStyle !== 'none';
btn.blur();
return res;
